route("GET", "/api/admin/summary", "admin", () => shop.summary());
route("GET", "/api/admin/products", "admin", () => shop.listProducts(true));
route("POST", "/api/admin/products", "admin", (ctx) => {
  const b = ctx.body, name = str(b.name, 120), price = Number(b.price), reorder = Number(b.reorder ?? 5), stock = Number(b.stock ?? 0);
  if (name.length < 2) throw err("Enter a product name.");
  if (![price, reorder, stock].every((n) => Number.isInteger(n) && n >= 0)) throw err("Price, stock and low-stock level must be whole numbers.");
  const r = db.prepare("INSERT INTO products(name,description,points,price,stock,reorder,image) VALUES(?,?,?,?,?,?,?)").run(name, str(b.description, 300), str(b.points, 200), price, stock, reorder, "");
  return shop.listProducts(true).find((p) => p.id === Number(r.lastInsertRowid));
});
route("PUT", "/api/admin/products/:id", "admin", (ctx) => {
  const id = Number(ctx.params.id), p = db.prepare("SELECT * FROM products WHERE id=?").get(id);
  if (!p) throw err("Product not found.", 404);
  const price = ctx.body.price === undefined ? p.price : Number(ctx.body.price), reorder = ctx.body.reorder === undefined ? p.reorder : Number(ctx.body.reorder);
  if (![price, reorder].every((n) => Number.isInteger(n) && n >= 0)) throw err("Enter a whole number.");
  const active = ctx.body.active === undefined ? p.active : ctx.body.active ? 1 : 0;
  db.prepare("UPDATE products SET price=?,reorder=?,active=?,name=? WHERE id=?").run(price, reorder, active, str(ctx.body.name ?? p.name, 120) || p.name, id);
  return shop.listProducts(true).find((x) => x.id === id);
});
route("POST", "/api/admin/products/:id/stock", "admin", (ctx) => shop.restock(Number(ctx.params.id), Number(ctx.body.delta), str(ctx.body.reason, 60) || "restock"));

route("GET", "/api/admin/orders", "admin", () => shop.listOrders({ limit: 200 }));
