// ---------- server ----------
const MIME = { ".html": "text/html; charset=utf-8", ".css": "text/css", ".js": "text/javascript", ".jpg": "image/jpeg", ".png": "image/png", ".svg": "image/svg+xml", ".ico": "image/x-icon", ".json": "application/json", ".webp": "image/webp", ".woff2": "font/woff2", ".map": "application/json" };
const SEC = {
  "X-Content-Type-Options": "nosniff", "X-Frame-Options": "DENY", "Referrer-Policy": "same-origin",
  "Content-Security-Policy": "default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; script-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",
};
const hits = new Map();
setInterval(() => hits.clear(), 60000).unref();

function send(res, status, body, type, extra = {}, cookies = []) {
  const headers = { ...SEC, "Content-Type": type, ...extra };
  if (cookies.length) headers["Set-Cookie"] = cookies;
  res.writeHead(status, headers); res.end(body);
}
const readBody = (req) => new Promise((resolve, reject) => {
  let n = 0; const chunks = [];
  req.on("data", (c) => { n += c.length; if (n > 200000) { reject(err("Request too large.", 413)); req.destroy(); } else chunks.push(c); });
  req.on("end", () => { try { resolve(chunks.length ? JSON.parse(Buffer.concat(chunks).toString()) : {}); } catch { reject(err("Invalid JSON.")); } });
  req.on("error", reject);
});

async function api(req, res, url) {
  const ctx = { ip: req.socket.remoteAddress || "", cookies: [], params: {}, body: {}, user: auth.userFromCookie(req.headers.cookie) };
  try {
    const c = (hits.get(ctx.ip) || 0) + 1; hits.set(ctx.ip, c);
    if (c > 300) throw err("Too many requests. Slow down.", 429);
    const r = routes.find((x) => x.method === req.method && x.re.test(url.pathname));
    if (!r) throw err("Not found.", 404);
    if (r.role && !ctx.user) throw err("Please log in.", 401);
    if (r.role === "admin" && ctx.user.role !== "admin") throw err("Admins only.", 403);
    if (req.method !== "GET") {
      if (!/application\/json/.test(req.headers["content-type"] || "")) throw err("Content-Type must be application/json.", 415);
      ctx.body = await readBody(req);
    }
    ctx.params = r.re.exec(url.pathname).groups || {};
    const out = await r.fn(ctx);
    if (out && out.raw) return send(res, 200, out.raw, out.type, { "Cache-Control": "no-store", ...(out.headers || {}) }, ctx.cookies);
    send(res, 200, JSON.stringify(out), "application/json", { "Cache-Control": "no-store" }, ctx.cookies);
  } catch (e) {
    const status = e.status || 500;
    if (status === 500) console.error(e);
    send(res, status, JSON.stringify({ error: status === 500 ? "Something went wrong on the server." : e.message }), "application/json", { "Cache-Control": "no-store" });
  }
}

// The React site is served from ./dist if you have built it yourself (npm run build),
// otherwise from the copy embedded at the bottom of this file.
const DIST = path.resolve(process.env.STATIC_DIR || path.join(__dirname, "dist"));
let USE_DIST = null, SITE = null;
function site() {
  if (SITE) return SITE;
  SITE = {};
  for (const [p, b64] of Object.entries(ASSETS)) SITE[p] = { type: MIME[path.extname(p)] || "application/octet-stream", body: Buffer.from(b64, "base64"), cache: p.startsWith("/img/") || p.startsWith("/chunk-") ? "public, max-age=86400" : "no-cache" };
  return SITE;
}
function serveStatic(req, res, url) {
  if (req.method !== "GET" && req.method !== "HEAD") return send(res, 405, "Method not allowed", "text/plain");
  let p; try { p = decodeURIComponent(url.pathname); } catch { return send(res, 400, "Bad request", "text/plain"); }
  if (p === "/") p = "/index.html";
  if (USE_DIST === null) USE_DIST = fs.existsSync(path.join(DIST, "index.html"));
  if (USE_DIST) {
    const file = path.normalize(path.join(DIST, p));
    if (!file.startsWith(DIST + path.sep) || path.basename(file).startsWith(".")) return send(res, 404, "Not found", "text/plain");
    return fs.readFile(file, (e, data) => {
      if (e) return send(res, 404, "Not found", "text/plain");
      const ext = path.extname(file);
      send(res, 200, data, MIME[ext] || "application/octet-stream", { "Cache-Control": p.startsWith("/assets/") || ext === ".jpg" ? "public, max-age=86400" : "no-cache" });
    });
  }
  const f = site()[p];
  if (!f) return send(res, 404, "Not found", "text/plain");
  send(res, 200, f.body, f.type, { "Cache-Control": f.cache });
}

http.createServer((req, res) => {
  let url; try { url = new URL(req.url, "http://localhost"); } catch { return send(res, 400, "Bad request", "text/plain"); }
  if (url.pathname.startsWith("/api/")) api(req, res, url); else serveStatic(req, res, url);
}).listen(PORT, () => console.log(`DK Store running at http://localhost:${PORT}   (admin: http://localhost:${PORT}/admin.html)`));

